{
  "segment_function": "The author examines the political standing of speech and action relative to homo faber and animal laborans, the role of common sense, and the distinct forms of alienation found in commercial and laboring societies.",
  "claims": [
    {
      "claim": "The ancient estimation of politics rests on the conviction that individuals appear and confirm themselves in unique distinctness through speech and action.",
      "claim_type": "author_position",
      "supporting_excerpt": "The root of the ancient estimation of politics is the conviction that man qua man, each individual in his unique distinctness, appears and confirms himself in speech and action, and that these activi ties, despite their material futility, possess an enduring quality of their own because they create their own remembrance.",
      "support_kind": "direct",
      "confidence": 1.0
    },
    {
      "claim": "Both homo faber and animal laborans are strictly unpolitical because they judge public activities in terms of usefulness to higher ends rather than value appearance and actualization.",
      "claim_type": "author_position",
      "supporting_excerpt": "Both, therefore, are, strictly speaking, unpolitical, and will incline to denounce action and speech as idleness, idle busybodyness and idle talk, and generally will judge public activities in terms of their usefulness to supposedly higher ends",
      "support_kind": "direct",
      "confidence": 1.0
    }
  ],
  "definitions": [
    {
      "term": "common sense",
      "definition": "The one sense that fits our five strictly individual senses and their particular data into reality as a whole, allowing us to recognize them as disclosures of reality."
    }
  ],
  "distinctions": [
    {
      "item_a": "homo faber",
      "item_b": "animal laborans",
      "distinction": "Homo faber views public activities in terms of making the world more useful and beautiful, whereas animal laborans views them in terms of making life easier and longer."
    }
  ]
}

